/**
 * The game's coach talent trees: the head coach's 13 subtrees (coordinators
 * use the first 11), every node with its name, description, cost, screen
 * position, parent/children links and branch title, each subtree's
 * archetype-node prerequisite, and the enums' display names.
 *
 * GENERATED by scripts/extract-coach-talents.ts — do not edit by hand.
 *
 * Slot i is the coach's TalentSubTreeStatus[i]; node index N is that row's
 * TalentStatusN. Node 0 is the archetype (gate) node; every other node has
 * exactly one parent and becomes purchasable when the parent is owned.
 * Archetype value 1 is "Schemer" in the save enum but "Tactician" on screen —
 * map by value.
 */
export interface CoachTalentNode {
  index: number;
  name: string;
  desc: string;
  /** Coach points the game charges. */
  cost: number;
  /** Screen row (0 = the archetype node) and column. */
  level: number;
  column: number;
  parent: number | null;
  children: number[];
  /** Branch heading the game shows on a level-1 node, when it has one. */
  branch: string | null;
}

export interface CoachTalentSubTree {
  slot: number;
  name: string;
  desc: string;
  type: 'Base' | 'Hybrid' | 'Specialty';
  /** CoachTalentArcheType value this subtree represents. */
  archetype: number;
  canBeDominant: boolean;
  /** What unlocks the archetype node in-game (the game evaluates it natively). */
  prereq: { title: string; desc: string; minLevel: number; spendPoints: number } | null;
  nodes: CoachTalentNode[];
}

