/** Coordinators run the same tree without the two head-coach specialties. */
export const COORDINATOR_TALENT_TREE: CoachTalentSubTree[] = HEAD_COACH_TALENT_TREE.slice(0, 11);

/** The tree for a save Position member ('HeadCoach' | 'OffensiveCoordinator' | 'DefensiveCoordinator'). */
export function coachTalentTree(position: string): CoachTalentSubTree[] {
  return position === 'HeadCoach' ? HEAD_COACH_TALENT_TREE : COORDINATOR_TALENT_TREE;
}
